class Cat:
    def speak(self):
        return "meow"

class Duck:
    def speak(self):
        return "quack"

for a in (Cat(), Duck()):
    print(a.speak())

class Suite:
    def __init__(self, tests):
        self.tests = tests

    def __len__(self):
        return len(self.tests)

s = Suite(["t1", "t2", "t3"])
print(len(s))

class Robot:
    def beep(self):
        return "beep"

def greet(x):
    return x.speak()

print(greet(Robot()))

class ConsoleOut:
    def write(self, msg):
        return f"console:{msg}"

class FileOut:
    def write(self, msg):
        return f"file:{msg}"

def flush(sink):
    print(sink.write("ok"))

flush(FileOut())

class Calc:
    def add(self, a, b):
        return a + b

    def add(self, a):
        return a + 1

c = Calc()
print(c.add(5))

class Mixer:
    def mix(self, a, b):
        return a + b

    def mix(self, a):
        return a * 2

print(Mixer().mix(1, 2))

class Wav:
    def play(self):
        return "wav"

s = Wav()
(hasattr(s, "play"), hasattr(s, "stop"))

class Parrot:
    speak = "polly"

def talk(a):
    return a.speak()

print(talk(Parrot()))
